    public function index(Request $r,AccountingContext $c){$v=$r->validate(['exchange_page'=>'nullable|integer|min:1','exchange_per_page'=>'nullable|integer|in:25,50,100','exchange_search'=>'nullable|string|max:50','exchange_currency'=>'nullable|string|max:10']);$cid=$c->companyId($r);$bid=$c->branchFilter($r);$exchangeSearch=trim((string)($v['exchange_search']??''));$exchangeRates=DB::table('exchange_rates')->where('company_id',$cid)->when($exchangeSearch!=='',fn($q)=>$q->where(function($x)use($exchangeSearch){$like='%'.$exchangeSearch.'%';$x->where('currency_code','like',$like)->orWhere('source','like',$like);}))->when(!empty($v['exchange_currency']),fn($q)=>$q->where('currency_code',strtoupper((string)$v['exchange_currency'])))->orderByDesc('valid_from')->orderByDesc('id')->paginate(min(100,max(25,(int)($v['exchange_per_page']??25))),['*'],'exchange_page',(int)($v['exchange_page']??1));return response()->json(['status'=>true,'data'=>[
        'settings'=>DB::table('company_settings')->where('company_id',$cid)->first(),
        'currencies'=>DB::table('company_currencies as cc')->join('currencies as c','c.currency_code','=','cc.currency_code')->where('cc.company_id',$cid)->select('c.*','cc.is_base','cc.is_active as company_active')->orderByDesc('cc.is_base')->get(),
        'available_currencies'=>DB::table('currencies')->where('is_active',1)->orderBy('currency_code')->get(['currency_code','currency_name','symbol','decimal_places']),
        'exchange_rates'=>$exchangeRates->items(),
        'exchange_rate_currency_codes'=>DB::table('exchange_rates')->where('company_id',$cid)->distinct()->pluck('currency_code'),
        'exchange_rates_pagination'=>['current_page'=>$exchangeRates->currentPage(),'last_page'=>$exchangeRates->lastPage(),'per_page'=>$exchangeRates->perPage(),'total'=>$exchangeRates->total(),'from'=>$exchangeRates->firstItem(),'to'=>$exchangeRates->lastItem()],
        'tax_codes'=>DB::table('tax_codes as t')->leftJoin('accounts as sa','sa.id','=','t.sales_tax_account_id')->leftJoin('accounts as pa','pa.id','=','t.purchase_tax_account_id')->where('t.company_id',$cid)->select('t.*','sa.account_code as sales_account_code','sa.account_name as sales_account_name','pa.account_code as purchase_account_code','pa.account_name as purchase_account_name')->orderBy('tax_code')->get(),
        'branches'=>DB::table('branches')->where('company_id',$cid)->where('is_active',1)->when($bid!==null,fn($q)=>$q->where('id',$bid))->orderBy('branch_name')->get(),
        'cost_centers'=>DB::table('cost_centers')->where('company_id',$cid)->where('is_active',1)->when($bid!==null,fn($q)=>$q->where(function($x)use($bid){$x->where('branch_id',$bid)->orWhereNull('branch_id');}))->orderBy('cost_center_code')->get(),
        'posting_accounts'=>DB::table('accounts')->where('company_id',$cid)->where('is_active',1)->where('is_group',0)->where('allow_posting',1)->orderBy('account_code')->get(),
